window.DiseaseRulesKB = {"version":"2024-nhc-4guides","updatedAt":"2026-08-30","meta":{"description":"疾病饮食规则知识库：从国家卫健委 4 项食养指南（2024 年版）结构化提取，供规则引擎按用户健康档案触发","sources":["国家卫生健康委办公厅《成人肥胖食养指南（2024年版）》国卫办食品函〔2024〕53号","国家卫生健康委办公厅《儿童青少年肥胖食养指南（2024年版）》国卫办食品函〔2024〕53号","国家卫生健康委办公厅《成人慢性肾脏病食养指南（2024年版）》国卫办食品函〔2024〕53号","国家卫生健康委办公厅《成人高尿酸血症与痛风食养指南（2024年版）》国卫办食品函〔2024〕53号"]},"conditions":[{"id":"obesity","name":"成人肥胖 / 减重","appliesTo":["adult"],"source":"《成人肥胖食养指南（2024年版）》","principles":["控制总能量摄入，保持合理膳食","少吃高能量食物，饮食清淡，限制饮酒","纠正不良饮食行为，科学进餐","多动少静，睡眠充足，作息规律","食养有道，合理选择食药物质","安全减重，达到并保持健康体重"],"flags":[{"category":"含糖饮料","terms":["可乐","汽水","碳酸饮料","果味饮料","乳酸菌饮料","奶茶","含糖饮料","冰糖雪梨","冰红茶"],"level":"warning","reason":"减重期应避免含糖饮料：液体糖不顶饱，最容易不知不觉喝超"},{"category":"油炸食品","terms":["油炸","炸鸡","薯条","薯片","油条","油饼","炸"],"level":"warning","reason":"高能量食物（≥400kcal/100g），指南建议减重期少吃"},{"category":"高糖零食","terms":["糖果","蜜饯","冰淇淋","雪糕","巧克力","蛋糕","甜甜圈","沙琪玛"],"level":"warning","reason":"指南点名的高能量食物，减重期尽量不选"},{"category":"加工肉制品","terms":["香肠","火腿肠","培根","腊肉","午餐肉","熏肉","肉脯"],"level":"warning","reason":"指南建议采购时尽量不选加工肉制品"},{"category":"动物脂肪/起酥油","terms":["肥肉","猪油","牛油","羊油","起酥油","人造奶油","植脂末","氢化植物油"],"level":"warning","reason":"高脂肪食材，减重期严格控制脂肪摄入"},{"category":"酒精","terms":["白酒","啤酒","黄酒","葡萄酒","料酒","酒精"],"level":"warning","reason":"每克酒精约 7kcal，远超碳水和蛋白质，减重期严格限制饮酒"}],"nutrientLimits":{"salt_g_day":"≤5","oil_g_day":"20~25","added_sugar_g_day":"≤25","energy_note":"每日能量摄入平均降低 30%~50%，或降低 500~1000kcal；男性 1200~1500kcal/日，女性 1000~1200kcal/日","macros":"脂肪供能比 20%~30%，蛋白质 15%~20%，碳水化合物 50%~60%；三餐供能比 3:4:3"},"tips":["主食以全谷物为主，至少占谷物的一半，减少精白米面","新鲜蔬菜每天 300~500g，深色蔬菜占一半以上；每天 3~5 种","水果每天约 200g，少选榴莲、香蕉、荔枝、鲜枣等高糖水果，不喝果汁","鱼虾蟹贝每周至少 2 次（每天 40~75g）；畜禽肉每周不超 500g，选纯瘦肉","蛋类每周 280~350g（不超过 7 个）","低脂或脱脂奶每天 300~500mL；豆制品选豆腐、无糖豆浆，避开油炸豆制品","坚果每周 50~70g（每天约 10g），首选原味","晚餐建议 17:00~19:00，餐后不再进食；按蔬菜→肉类→主食顺序进餐","理想减重目标：6 个月减当前体重 5%~10%，每月 2~4kg"]},{"id":"obesity_child","name":"儿童青少年肥胖","appliesTo":["child_1_3","child_3_12"],"source":"《儿童青少年肥胖食养指南（2024年版）》","principles":["小份多样，保持合理膳食结构","辨证施食，因人因时因地制宜","良好饮食行为，促进长期健康","积极身体活动，保持身心健康","多方合作，创造社会支持环境","定期监测，科学指导体重管理"],"flags":[{"category":"含糖饮料","terms":["可乐","汽水","碳酸饮料","果味饮料","乳酸菌饮料","奶茶","含糖饮料","冰糖雪梨","冰红茶"],"level":"warning","reason":"含糖饮料是儿童肥胖的重要推手，指南建议减少摄入"},{"category":"油炸食品","terms":["油炸","炸鸡","薯条","薯片","油条"],"level":"warning","reason":"高油高能量密度食物，肥胖儿童应少吃"},{"category":"甜点糖果","terms":["糖果","甜点","冰淇淋","雪糕","巧克力","蛋糕","蜜饯"],"level":"warning","reason":"高糖高能量密度，指南建议肥胖儿童减少摄入"}],"nutrientLimits":{"energy_note":"肥胖儿童膳食能量在正常体重儿童需要量基础上减少约 20%，吃饭八分饱","milk_ml_day":"2~5 岁 350~500mL；6~17 岁 300mL 以上","food_variety":"每天 12 种以上食物，每周 25 种以上"},"tips":["吃饭八分饱，控制膳食总能量","多选天然新鲜食材，提高鱼类、蔬菜、大豆及制品比例","控制精白米面，增加低血糖生成指数的全谷物和杂豆","减少高油、高盐、高糖和能量密度较高的食物","保证优质蛋白质：鱼、禽、蛋、瘦肉、奶及奶制品、大豆及制品","选择小份量食物实现食物多样，每天 12 种、每周 25 种以上"]},{"id":"ckd","name":"成人慢性肾脏病","appliesTo":["adult"],"source":"《成人慢性肾脏病食养指南（2024年版）》","principles":["食物多样，分期选配","能量充足，体重合理，谷物适宜，主食优化","蛋白适量，合理摄入鱼禽豆蛋奶肉","蔬菜充足，水果适量","少盐控油，限磷控钾","适量饮水，量出为入","合理选择食药物质，调补有道","合理选择营养健康食品，改善营养状况","规律进餐，限制饮酒，适度运动","定期监测，强化自我管理"],"flags":[{"category":"高盐/隐形盐","terms":["食盐","食用盐","酱油","味精","鸡精","豆瓣酱","腐乳","酱料","蚝油"],"level":"warning","reason":"肾病每日盐不超 5g（水肿者 3g），调味品都是隐形盐"},{"category":"烟熏烧烤腌制","terms":["烟熏","烧烤","腌制","咸菜","榨菜","泡菜","腊肉","咸鱼","熏"],"level":"warning","reason":"指南建议肾病患者尽量不吃烟熏、烧烤、腌制等过度加工食品"},{"category":"含磷添加剂","terms":["磷酸盐","三聚磷酸钠","焦磷酸钠","六偏磷酸钠","磷酸氢","磷酸二氢","磷酸"],"level":"warning","reason":"加工食品中的含磷添加剂吸收率远高于天然食物，肾病需限磷（每日 800~1000mg）"},{"category":"浓肉汤/高汤","terms":["肉汤","骨汤","老火汤","高汤","浓汤"],"level":"warning","reason":"浓肉汤高钾高磷，肾病患者应限制或禁食"},{"category":"酒精","terms":["白酒","啤酒","黄酒","葡萄酒","酒精"],"level":"warning","reason":"肾病患者应限酒或不饮酒"}],"nutrientLimits":{"salt_g_day":"≤5（水肿者 ≤3；严重水肿无盐膳食钠＜1000mg）","phosphorus_mg_day":"800~1000","potassium_mg_day":"高钾血症时 2000~3000，避免浓肉汤、菜汤，烹调先飞水弃汤","protein_note":"3~5 期低蛋白饮食：每日每公斤理想体重 0.6g，优质蛋白占 50% 以上；理想体重(kg)=身高(cm)-105","oil_g_day":"25~40，脂肪供能比 ≤35%","water_ml_day":"无水肿且尿量正常者 1500~1700；水肿者量出为入","food_variety":"每日 12 种以上，每周 25 种以上"},"tips":["1~2 期：植物性食物为主，餐餐有蔬菜 300~500g，深色占一半","3~5 期：低蛋白饮食，可用红薯、土豆、莲藕、山药、绿豆粉丝替代部分谷物","红肉（猪牛羊）尽量少吃，每周 1~2 次、每次不超 50g；优先鱼禽白肉","学会看营养标签，避开含磷添加剂多的加工食品","烹调选清蒸、炖、焖、煮；先飞水后烹调可减少磷和钾","5 期透析阶段仍需植物性食物为主，按医嘱调整动物性食物"]},{"id":"hyperuricemia","name":"高尿酸血症 / 痛风","appliesTo":["adult"],"source":"《成人高尿酸血症与痛风食养指南（2024年版）》","principles":["食物多样，限制嘌呤","蔬奶充足，限制果糖","足量饮水，限制饮酒","科学烹饪，少食生冷","吃动平衡，健康体重","辨证辨体，因人施膳","因地因时，择膳相宜"],"flags":[{"category":"酒精","terms":["啤酒","黄酒","白酒","酒精"],"level":"danger","reason":"酒精抑制尿酸排泄，啤酒黄酒嘌呤还高，痛风人群严格限制"},{"category":"高果糖","terms":["果葡糖浆","高果糖","玉米糖浆","含糖饮料","可乐","奶茶"],"level":"warning","reason":"果糖代谢促进尿酸生成，指南建议限制果糖摄入"},{"category":"动物内脏/高汤","terms":["动物内脏","肝","肾","脑","肠","肉汤","骨汤","高汤","火锅汤"],"level":"warning","reason":"动物内脏和浓汤嘌呤极高，痛风人群避免"}],"nutrientLimits":{"purine_note":"避免高嘌呤食物（150~1000mg/100g），限制中嘌呤（75~150mg/100g），详见嘌呤知识库 236 条","water_ml_day":"2000~3000（心肾功能正常者），促进尿酸排泄","fructose_note":"限制含果糖饮料和食品"},"tips":["每天饮水 2000~3000mL，白开水、淡茶水为宜","新鲜蔬菜每天不少于 500g，深色蔬菜占一半以上","低脂或脱脂奶每天 300mL 以上","限制果糖：少喝含糖饮料，蜂蜜也要控制","严格限酒，急性期禁酒；啤酒、黄酒最危险","科学烹饪：肉类先焯水弃汤再煮，少喝肉汤"]}]};
